package com.nuvio.app.features.player.desktop

import java.nio.file.Path

// Fork-only: types shared by the shader catalog, the user-folder scanner and the player hooks.

// Subfolder name under both the app data dir (user shaders) and the cache dir (prepared files).
internal const val LIBMPV_SHADERS_DIR = "shaders"

// Which mpv video output a shader needs. Hand-ported shaders run on gpu (crt-guest-advanced-ntsc breaks
// on gpu-next); shaders generated by mpv-libretro use //!PARAM, which only gpu-next parses.
internal enum class LibmpvShaderRenderer(val vo: String) {
    Gpu("gpu,"),
    GpuNext("gpu-next,gpu,"),
}

// One entry in the player's shader menu. [files] are the .glsl files in mpv load order; preparing them
// (resource extraction, texture conversion) touches the disk, so it happens once, on first use.
internal class LibmpvShaderPreset(
    val id: String,
    val name: String,
    val user: Boolean,
    val renderer: LibmpvShaderRenderer,
    // Why the preset can't be used; the menu shows it greyed out with this text.
    val problem: String? = null,
    files: () -> List<Path> = { emptyList() },
) {
    val files: List<Path> by lazy(files)
    val usable: Boolean get() = problem == null
}

// A file whose //!TEXTURE blocks can satisfy another shader's //!BIND lines.
internal class LibmpvShaderTextures(val names: Set<String>, val path: () -> Path)
